from pathlib import Path

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")

replacements = [
    (
        "- 成功：敵の動きを事前に察知する。次に発生する戦闘で分隊は先制攻撃を行う。",
        "- 成功：敵の動きを事前に察知する。次に発生する戦闘では分隊側が先攻となる。",
    ),
    (
        "- 近づく。混乱に乗じて前進する。次の戦闘で分隊が先制攻撃を行う。",
        "- 近づく。混乱に乗じて前進する。次の戦闘では分隊側が先攻となる。",
    ),
    (
        "- 失敗：警報が鳴り響く。次のd66の十の位は5になる。さらに、次に発生する戦闘は敵が先制攻撃を行う。",
        "- 失敗：警報が鳴り響く。次のd66の十の位は5になる。さらに、次に発生する戦闘では敵側が先攻となる。",
    ),
    (
        "- 先制：この戦闘ではシナリオ固有効果として、分隊側が必ず先制攻撃を行う。",
        "- 先攻：この戦闘ではシナリオ固有効果として、分隊側が必ず先攻となる。",
    ),
    (
        "- 先制権に関する持ち越し効果だけは1つのみ保持する。「分隊が先制攻撃を行う」または「敵が先制攻撃を行う」を新たに得た場合、それ以前に保持していた先制権の指定を上書きする。",
        "- 先攻に関する持ち越し効果だけは1つのみ保持する。「分隊側が先攻」または「敵側が先攻」を新たに得た場合、それ以前に保持していた先攻指定を上書きする。この持ち越し先攻は行動順だけを変更し、敵の反応は変更しない。Core v1.01の遭遇時選択【先制攻撃】を行ったものとしては扱わない。",
    ),
    (
        "- 出目52【怒号の群衆】の「分隊側が必ず先制攻撃を行う」など、発生した戦闘そのものに先制権が明記されている場合は、その戦闘固有の記載を最優先する。",
        "- 出目52【怒号の群衆】の「分隊側が必ず先攻となる」など、発生した戦闘そのものに先攻が明記されている場合は、その戦闘固有の記載を最優先する。",
    ),
]

for old, new in replacements:
    count = s.count(old)
    if count != 1:
        raise SystemExit(f"expected exactly one match for {old!r}, got {count}")
    s = s.replace(old, new, 1)

scenario.write_text(s, encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")

# Keep the previous carryover record consistent with the approved terminology.
audit_replacements = [
    (
        "- 先制権だけは1つのみ保持し、新たに得た「分隊先制」または「敵先制」が、それ以前の持ち越し先制権を上書きする。",
        "- 先攻指定だけは1つのみ保持し、新たに得た「分隊側先攻」または「敵側先攻」が、それ以前の持ち越し先攻指定を上書きする。",
    ),
    (
        "- 出目52【怒号の群衆】の「必ず分隊側が先制」など、戦闘そのものに先制権が明記されている場合は、戦闘固有の指定を最優先する。",
        "- 出目52【怒号の群衆】の「必ず分隊側が先攻」など、戦闘そのものに先攻が明記されている場合は、戦闘固有の指定を最優先する。",
    ),
    (
        "これにより、出目13／32の分隊先制と出目45の敵先制が競合した場合は、後から得た情報・警戒状態が優先される。数値系の持ち越し効果は同時に処理でき、戦闘固有ルールは持ち越し状態より優先する。",
        "これにより、出目13／32の分隊側先攻と出目45の敵側先攻が競合した場合は、後から得た情報・警戒状態が優先される。数値系の持ち越し効果は同時に処理でき、戦闘固有ルールは持ち越し状態より優先する。",
    ),
]
for old, new in audit_replacements:
    count = a.count(old)
    if count != 1:
        raise SystemExit(f"audit expected exactly one match for {old!r}, got {count}")
    a = a.replace(old, new, 1)

heading = "## 44. Black Sun 持ち越し先攻とCore【先制攻撃】の区別 — 採用済み"
section = """

## 44. Black Sun 持ち越し先攻とCore【先制攻撃】の区別 — 採用済み

ユーザー承認により、出目13／32／45等の「次の戦闘」の先制指定は、Core v1.01の遭遇時選択【先制攻撃】とは区別し、行動順だけを変更する【先攻】として扱う。

- 出目13【壊れた無線機】成功時は「次に発生する戦闘では分隊側が先攻」とする。
- 出目32【銃撃戦の残響】で接近した場合も「次の戦闘では分隊側が先攻」とする。
- 出目45【警戒線突破】失敗時は「次に発生する戦闘では敵側が先攻」とする。
- これらの持ち越し先攻は行動順のみを変更し、敵の【反応】そのものは変更しない。
- したがって、分隊側先攻を得ても、Core v1.01でプレイヤーが遭遇時に【先制攻撃】を選んだものとは扱わず、敵反応を自動的に【死ぬまで戦う】へ変更しない。
- 出目52【怒号の群衆】のような戦闘固有の先攻指定は、前項43どおり持ち越し先攻より優先する。
- 用語上の混同を避けるため、本シナリオの該当する持ち越し効果・戦闘固有指定は「先制攻撃」ではなく「先攻」と表記する。

これにより、「敵の反応」と「戦闘開始時の行動順」を独立して処理でき、偵察・警報等で得た先攻効果が意図せず敵の撤退可否まで変更することを防ぐ。
"""
if heading not in a:
    a = a.rstrip() + section + "\n"
audit.write_text(a, encoding="utf-8")
